@pytest.mark.requires_command(Cmd.TROPIC_ERASE_ALL_SLOTS)
def test_tropic_erase_all_slots(tropic_prodtest: TropicProdtest) -> None:
    with tropic_prodtest(
        tropic_model_configfile=DEFAULT_FIRMWARE_TROPIC_MODEL_CONFIGFILE
    ) as session:
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_ERASE_ALL_SLOTS))

    state = session.state()

    assert state.pairing_key_state(1) == "written"
    assert state.pairing_key_state(2) == "written"

    for i in range(_ECC_SLOT_COUNT):
        assert not state.ecc_key_is_present(i), f"ecc key {i} is not erased"
    for slot in range(_R_MEM_SLOT_COUNT):
        assert state.slot_is_erased(slot), f"slot {slot} not erased"


@pytest.mark.requires_command(
    Cmd.TROPIC_STRESS_INIT,
    Cmd.TROPIC_STRESS_MAC_AND_DESTROY,
    Cmd.TROPIC_STRESS_SESSION,
    Cmd.TROPIC_STRESS_TEST,
    Cmd.TROPIC_TEST_COUNTER,
    Cmd.TROPIC_TEST_MAC_AND_DESTROY,
    Cmd.TROPIC_TEST_RMEM,
    Cmd.TROPIC_TEST_SIGN,
    Cmd.TROPIC_TESTS_CLEANUP,
)
def test_tropic_test_commands(tropic_prodtest: TropicProdtest, tmp_path: Path) -> None:
    with tropic_prodtest() as session:
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_STRESS_INIT))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_STRESS_SESSION))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_STRESS_MAC_AND_DESTROY))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_STRESS_TEST))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_TEST_MAC_AND_DESTROY))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_TEST_RMEM))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_TEST_COUNTER))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_TEST_SIGN))
        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_TESTS_CLEANUP))

        # `tropic-test-rng` returns an error because the random number generator in the
        # tropic emulator repeats the same 4 bytes forever
        resp = assert_command_fails(
            session.client, ProdtestCommand(Cmd.TROPIC_TEST_RNG)
        )
        assert resp.error_code == PRODTEST_ERR_TROPIC_TEST_RNG_REPEAT

        session.client.command_ok(ProdtestCommand(Cmd.TROPIC_TESTS_CLEANUP))

    state = session.state()
    for i in range(_FIRST_TEST_ECC_SLOT, _ECC_SLOT_COUNT):
        assert not state.ecc_key_is_present(i), f"ecc key {i} is not erased"
    for slot in range(_FIRST_TEST_R_MEM_SLOT, _R_MEM_SLOT_COUNT):
        assert state.slot_is_erased(slot), f"slot {slot} not erased"


@pytest.mark.requires_command(Cmd.TROPIC_SET_SENSORS)
def test_tropic_set_sensors(tropic_prodtest: TropicProdtest) -> None:
    sensors_new_value = 4294705152

    with tropic_prodtest() as session:
        session.client.command_ok(
            ProdtestCommand(Cmd.TROPIC_SET_SENSORS, f"{sensors_new_value:04X}")
        )

    state = session.state()
    assert state.r_config.get("cfg_sensors") == sensors_new_value
    for i in range(_ECC_SLOT_COUNT):
        assert not state.ecc_key_is_present(i), f"ecc key {i} is not erased"
    for slot in range(_R_MEM_SLOT_COUNT):
        assert state.slot_is_erased(slot), f"slot {slot} not erased"


